// 单次完成hash计算
void hash_256_demo_single_calc(void) {
    HASH_HandleTypeDef pParas;
    uint32_t hash_out[384 / 8];
    HASH_InitTypeDef sha256_cfg = {SEA_SHA_256, HASH_GENERAL_MODE_EN, {0, 0}};

    if (SEA_SUCCESS != LL_HASH_init(&pParas, (const HASH_InitTypeDef *)&sha256_cfg)) {
        printf("hash_init return Fail!!!\n");
        return;
    }
    if (SEA_SUCCESS != LL_HASH(&pParas, (const hashData_t *)(sha256_requst), sizeof(sha256_requst), CypherDatasIsTheLast, (hashData_t *)hash_out)) {
        printf("hash return Fail!!!\n");
        return;
    }
    if (0U == memcmp((const uint8_t *)sha256_expected, (const uint8_t *)hash_out, sizeof(sha256_expected))) {
        printf("hash out compare Pass\n");
    } else {
        printf("hash out compare Fail!!!\n");
    }
}

