// 分多次完成hash计算
void hash_384_demo_multi_calc(void) {
    HASH_InitTypeDef hash_cfg = {
        SEA_SHA_384,
        HASH_GENERAL_MODE_EN,
        {0, 0},
    };
    HASH_HandleTypeDef pParas;
    uint32_t hash_out[384 / 8];

    if (SEA_SUCCESS != LL_HASH_init(&pParas, (const HASH_InitTypeDef *)&hash_cfg)) {
        printf("hash_init return Fail!!!\n");
        return;
    }
    // when is_last = CypherDatasNotTheLast, size = 128*N
    if (SEA_SUCCESS !=
        LL_HASH(&pParas, (const hashData_t *)(sha_384_requst_size_1344), NBLOCK_DATA_SHA_384_512 * sizeof(uint32_t), CypherDatasNotTheLast, (hashData_t *)hash_out)) {
        printf("hash return Fail!!!\n");
        return;
    }
    if (SEA_SUCCESS != LL_HASH(&pParas, (const hashData_t *)(&sha_384_requst_size_1344[NBLOCK_DATA_SHA_384_512 * sizeof(uint32_t)]),
                               sizeof(sha_384_requst_size_1344) - NBLOCK_DATA_SHA_384_512 * sizeof(uint32_t), CypherDatasIsTheLast, (hashData_t *)hash_out)) {
        printf("hash return Fail!!!\n");
        return;
    }
    if (0 == memcmp((const uint8_t *)sha_384_expected_size_1344, (const uint8_t *)hash_out, sizeof(sha_384_expected_size_1344))) {
        printf("hash out compare Pass\n");
    } else {
        printf("hash out compare Fail!!!\n");
    }
}

