// 随意数据长度,完成hash计算
void hash_384_demo_rand_size_calc(void) {
    HASH_InitTypeDef hash_cfg = {
        SEA_SHA_384,
        HASH_GENERAL_MODE_EN,
        {0, 0},
    };
    HASH_HandleTypeDef pParas;
    uint32_t hash_out[384 / 8];
#ifdef HASH_CRYPT_ITEMS_IN_BYTES
    uint8_t rand_size[3] = {1, 2, 3};
#else
    uint8_t rand_size[4] = {4, 8, 12};
#endif

    if (SEA_SUCCESS != LL_HASH_init(&pParas, (const HASH_InitTypeDef *)&hash_cfg)) {
        printf("hash_init return Fail!!!\n");
        return;
    }
    // when is_last = CypherDatasNotTheLast, size = 128*N
    if (SEA_SUCCESS != LL_HASH(&pParas, (const hashData_t *)(sha_384_requst_size_1344), rand_size[0], CypherDatasNotTheLast, (hashData_t *)0)) {
        printf("hash return Fail!!!\n");
        return;
    }
    if (SEA_SUCCESS != LL_HASH(&pParas, (const hashData_t *)(&sha_384_requst_size_1344[rand_size[0]]), rand_size[1], CypherDatasNotTheLast, (hashData_t *)0)) {
        printf("hash return Fail!!!\n");
        return;
    }
    if (SEA_SUCCESS != LL_HASH(&pParas, (const hashData_t *)(&sha_384_requst_size_1344[rand_size[0] + rand_size[1]]), rand_size[2], CypherDatasNotTheLast, 0)) {
        printf("hash return Fail!!!\n");
        return;
    }
    if (SEA_SUCCESS != LL_HASH(&pParas, (const hashData_t *)(&sha_384_requst_size_1344[rand_size[0] + rand_size[1] + rand_size[2]]),
                               sizeof(sha_384_requst_size_1344) - rand_size[0] - rand_size[1] - rand_size[2], CypherDatasIsTheLast, (hashData_t *)hash_out)) {
        printf("hash return Fail!!!\n");
        return;
    }
    if (0 == memcmp((const uint8_t *)sha_384_expected_size_1344, (const uint8_t *)hash_out, sizeof(sha_384_expected_size_1344))) {
        printf("hash out compare Pass\n");
    } else {
        printf("hash out compare Fail!!!\n");
    }
}

